      SUBROUTINE FNCORR(KNAME,LNAME,INAME)C---- FIND AND DECODE REFERENCE TO BEAM MATRIX CORRELATIONC-----------------------------------------------------------------      CHARACTER*15    KNAME      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'PARDAT.CIN'C----------------------------------------------------------------      CHARACTER*15    KNAMM      CHARACTER*1     KLETS(8)      EQUIVALENCE     (KNAMM,KLETS(1))      INTEGER         IARR(6)      DATA            IARR /0,0,1,3,6,10/C      KNAMM = KNAME      INAME = 0C      IF (LNAME .GE. 4) GO TO 100      IF (KLETS(1) .EQ. 'C') THEN        IND1 = INDEX('123456',KLETS(2))        IND2 = INDEX('123456',KLETS(3))        IF (IND1 .EQ. 0 .OR. IND2 .EQ. 0) GO TO 100        IF (IND1 .GT. 6 .OR. IND2 .GT. 6) GO TO 100        IF (IND1 .EQ. IND2) GO TO 100        IF (IND1 .LT. IND2) THEN          ISAVE = IND1          IND1 = IND2          IND2 = ISAVE        ENDIF        IPARM = IARR(IND1) + IND2        INAME = IPARM      ENDIFC  100 CONTINUE      RETURN      END